const body = $json.body || $json;
const now = new Date().toISOString();
const generatedId = `REQ-${Date.now().toString(36)}-${Math.random().toString(36).slice(2, 8)}`.toUpperCase();
const rawMessage = typeof body.raw_message === 'string' ? body.raw_message.trim() : '';
const validationErrors = [];
if (!rawMessage) validationErrors.push('raw_message is required and must be a non-empty string');
return [{ json: {
  request_id: body.request_id || generatedId,
  source: body.source || 'Unknown',
  received_at: body.received_at || now,
  raw_message: rawMessage,
  input_valid: validationErrors.length === 0,
  validation_errors: validationErrors,
  workflow_version: $env.WORKFLOW_VERSION || '1.0.0',
