const normalized = $('Normalize Input').first().json;
const previousErrors = $('Parse and Validate JSON').first().json.validation_errors || [];
const allowedCategories = ['Bug Report','Feature Request','Billing Issue','Technical Question','Incident/Outage'];
const allowedPriorities = ['Low','Medium','High'];
const allowedUrgency = ['None','Low','Medium','High'];
function asStringOrNull(value) { return typeof value === 'string' && value.trim() ? value.trim() : value == null ? null : null; }
function normalizeAmount(amount, index, errors) {
  if (!amount || typeof amount !== 'object') { errors.push(`identifiers.amounts[${index}] must be an object`); return null; }
  const label = typeof amount.label === 'string' && amount.label.trim() ? amount.label.trim() : null;
  const value = typeof amount.value === 'number' ? amount.value : Number(String(amount.value ?? '').replace(/[^0-9.-]/g, ''));
  if (!label) errors.push(`identifiers.amounts[${index}].label is required`);
  if (!Number.isFinite(value)) errors.push(`identifiers.amounts[${index}].value must be numeric`);
  return { label: label || 'other_amount', value: Number.isFinite(value) ? value : 0, currency: typeof amount.currency === 'string' && amount.currency.trim() ? amount.currency.trim() : 'USD' };
}
function fallback(reason, extra = []) {
  return [{ json: { ...normalized, llm_valid: false, validation_errors: [reason, ...previousErrors, ...extra].filter(Boolean), category: 'Technical Question', priority: 'Low', confidence_score: 0, core_issue: 'The request could not be classified automatically.', identifiers: { account_reference: null, invoice_number: null, error_code: null, amounts: [], time_references: [], authentication_provider: null, affected_users: null }, urgency_signal: 'None', urgency_reason: 'LLM output was unavailable or invalid after retry.', customer_impact: 'Unknown impact.', requires_follow_up_information: true, missing_information: ['Manual review required'], human_readable_summary: 'The request could not be classified automatically after retry. Human Review should inspect the original customer message.' } }];
}
function validateParsed(parsed) {
  const errors = [];
  const out = { ...parsed };
  if (!allowedCategories.includes(out.category)) errors.push('Invalid category');
  if (!allowedPriorities.includes(out.priority)) errors.push('Invalid priority');
  if (!Number.isInteger(out.confidence_score) || out.confidence_score < 0 || out.confidence_score > 100) errors.push('Invalid confidence_score');
  if (typeof out.core_issue !== 'string' || !out.core_issue.trim()) errors.push('core_issue must be a non-empty string');
  if (!out.identifiers || typeof out.identifiers !== 'object' || Array.isArray(out.identifiers)) errors.push('identifiers must be an object');
  const ids = out.identifiers && typeof out.identifiers === 'object' && !Array.isArray(out.identifiers) ? out.identifiers : {};
  const amounts = Array.isArray(ids.amounts) ? ids.amounts.map((a, i) => normalizeAmount(a, i, errors)).filter(Boolean) : [];
  if (!Array.isArray(ids.amounts)) errors.push('identifiers.amounts must be an array');
  if (!Array.isArray(ids.time_references)) errors.push('identifiers.time_references must be an array');
  if (!allowedUrgency.includes(out.urgency_signal)) errors.push('Invalid urgency_signal');
  if (typeof out.urgency_reason !== 'string' || !out.urgency_reason.trim()) errors.push('urgency_reason must be a non-empty string');
  if (typeof out.customer_impact !== 'string' || !out.customer_impact.trim()) errors.push('customer_impact must be a non-empty string');
  if (typeof out.requires_follow_up_information !== 'boolean') errors.push('requires_follow_up_information must be boolean');
  if (!Array.isArray(out.missing_information)) errors.push('missing_information must be an array');
  if (typeof out.human_readable_summary !== 'string' || !out.human_readable_summary.trim()) errors.push('human_readable_summary must be a non-empty string');
  out.identifiers = { account_reference: asStringOrNull(ids.account_reference), invoice_number: asStringOrNull(ids.invoice_number), error_code: asStringOrNull(ids.error_code), amounts, time_references: Array.isArray(ids.time_references) ? ids.time_references.filter(v => typeof v === 'string' && v.trim()).map(v => v.trim()) : [], authentication_provider: asStringOrNull(ids.authentication_provider), affected_users: typeof ids.affected_users === 'string' || typeof ids.affected_users === 'number' ? ids.affected_users : null };
  out.missing_information = Array.isArray(out.missing_information) ? out.missing_information.filter(v => typeof v === 'string' && v.trim()).map(v => v.trim()) : [];
  return { out, errors };
}
try {
  if ($json.error) return fallback('Groq retry call failed or timed out');
  const content = $json.choices?.[0]?.message?.content;
  if (!content) return fallback('Retry response content missing');
  const parsed = typeof content === 'string' ? JSON.parse(content) : content;
  const { out, errors } = validateParsed(parsed);
  if (errors.length) return fallback('Retry validation failed', errors);
  return [{ json: { ...normalized, ...out, llm_valid: true, validation_errors: [] } }];
} catch (error) {
  return fallback(`Retry malformed JSON: ${error.message}`);
}

const record = { ...$json };
const amounts = Array.isArray(record.identifiers?.amounts) ? record.identifiers.amounts : [];
function numeric(v) { return typeof v === 'number' ? v : Number(String(v).replace(/[^0-9.-]/g, '')); }
const billed = amounts.find(a => /billed|charge|invoice/i.test(a.label || ''));
const expected = amounts.find(a => /expected|contract|rate/i.test(a.label || ''));
let a = billed ? numeric(billed.value) : null;
let b = expected ? numeric(expected.value) : null;
if ((!Number.isFinite(a) || !Number.isFinite(b)) && amounts.length >= 2) {
  a = numeric(amounts[0].value);
  b = numeric(amounts[1].value);
}
record.billing_difference = Number.isFinite(a) && Number.isFinite(b) ? Math.abs(a - b) : null;
return [{ json: record }];

const record = { ...$json };
const text = `${record.raw_message || ''} ${record.identifiers?.authentication_provider || ''}`.toLowerCase();
let queue = 'Engineering Support';
if (record.category === 'Feature Request') queue = 'Product Management';
if (record.category === 'Billing Issue') queue = 'Billing Operations';
if (record.category === 'Incident/Outage') queue = 'Incident Response';
if (record.category === 'Technical Question') queue = /(sso|authentication|auth provider|okta|identity|permission|security)/i.test(text) ? 'Identity & Security' : 'Engineering Support';
if (!record.llm_valid) queue = 'Engineering Support';
record.recommended_queue = queue;
return [{ json: record }];

const record = { ...$json };
const reasons = [];
const message = String(record.raw_message || '').toLowerCase();
const affected = String(record.identifiers?.affected_users || '').toLowerCase();
const phrases = ['outage','down for all users','dashboard stopped loading','multiple users affected','service unavailable'];
if (!record.llm_valid) reasons.push(`LLM output invalid or incomplete: ${(record.validation_errors || []).join('; ')}`);
if ((record.confidence_score ?? 0) < 70) reasons.push('Confidence score below 70');
if (record.category === 'Incident/Outage' || /(outage|unavailable|stopped loading|down)/i.test(message)) reasons.push('Message indicates service outage or unavailability');
if (/(multiple users|all users|everyone|company-wide)/i.test(`${message} ${affected}`)) reasons.push('Multiple users or all users are affected');
for (const phrase of phrases) if (message.includes(phrase)) reasons.push(`Message contains escalation phrase: ${phrase}`);
if (record.category === 'Billing Issue' && typeof record.billing_difference === 'number' && record.billing_difference > 500) reasons.push('Billing discrepancy greater than $500');
record.escalation_reasons = [...new Set(reasons)];
record.escalation_flag = record.escalation_reasons.length > 0;
return [{ json: record }];

const record = { ...$json };
record.final_queue = record.escalation_flag ? 'Human Review' : record.recommended_queue;
return [{ json: record }];
